using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
public sealed class CompanionInstructionText {public string profile="",text="",sourceHash="";public int version=1;}
internal static class CompanionInstructions {
 internal const int Version=1;static readonly System.Web.Script.Serialization.JavaScriptSerializer Json=new System.Web.Script.Serialization.JavaScriptSerializer{MaxJsonLength=1024*1024};
 static readonly string[][] openings={new[]{"Rendez-vous","Va"},new[]{"Dirigez-vous","Dirige-toi"},new[]{"Déplacez-vous","Déplace-toi"},new[]{"Retournez","Retourne"},new[]{"Revenez","Reviens"},new[]{"Allez","Va"},new[]{"Parlez","Parle"},new[]{"Discutez","Discute"},new[]{"Interagissez","Interagis"},new[]{"Cliquez","Clique"},new[]{"Récupérez","Récupère"},new[]{"Récuperez","Récupère"},new[]{"Ramassez","Ramasse"},new[]{"Achetez","Achète"},new[]{"Apportez","Apporte"},new[]{"Donnez","Donne"},new[]{"Prenez","Prends"},new[]{"Entrez","Entre"},new[]{"Sortez","Sors"},new[]{"Traversez","Traverse"},new[]{"Empruntez","Emprunte"},new[]{"Utilisez","Utilise"},new[]{"Ouvrez","Ouvre"},new[]{"Fermez","Ferme"},new[]{"Lisez","Lis"},new[]{"Choisissez","Choisis"},new[]{"Validez","Valide"},new[]{"Acceptez","Accepte"},new[]{"Refusez","Refuse"},new[]{"Attendez","Attends"},new[]{"Combattez","Combats"},new[]{"Affrontez","Affronte"},new[]{"Battez","Bats"},new[]{"Tuez","Tue"},new[]{"Équipez-vous","Équipe-toi"},new[]{"Equipez-vous","Équipe-toi"},new[]{"Munissez-vous","Munis-toi"},new[]{"Assurez-vous","Assure-toi"},new[]{"N’oubliez pas","N’oublie pas"},new[]{"N'oubliez pas","N'oublie pas"},new[]{"Ne quittez pas","Ne quitte pas"},new[]{"Ne tuez pas","Ne tue pas"},new[]{"Vous devez","Tu dois"},new[]{"Vous devrez","Tu devras"},new[]{"Vous pouvez","Tu peux"},new[]{"Vous pourrez","Tu pourras"},new[]{"Il vous faudra","Il te faudra"},new[]{"Il vous faut","Il te faut"}};
 internal static string Rewrite(string source){if(String.IsNullOrWhiteSpace(source))return source??"";return String.Join("\n",source.Replace("\r\n","\n").Split('\n').Select(line=>{if(line.IndexOfAny(new[]{'"','«','»','“','”'})>=0)return line;if(Regex.IsMatch(line,@"^\s*(?:(?:•|[-–]|[0-9]+[.)])\s*)?(?:Si|Sinon|Sauf|Selon|Lorsque|Quand|Pour les|En tant que)\b",RegexOptions.IgnoreCase))return line;foreach(var rule in openings){string pattern=@"^(\s*(?:(?:•|[-–]|[0-9]+[.)])\s*)?)"+Regex.Escape(rule[0])+@"\b";if(Regex.IsMatch(line,pattern,RegexOptions.IgnoreCase))return Regex.Replace(line,pattern,m=>m.Groups[1].Value+rule[1],RegexOptions.IgnoreCase);}return line;}));}
 internal static string Profile(DofusCharacter c){if(c==null)return "Tes consignes";var parts=new List<string>{c.name};int index=Array.IndexOf(DofusCompanion.Classes,c.classCode);if(index>0)parts.Add(DofusCompanion.ClassNames[index]);if(c.alignment=="Bonta")parts.Add("Bontarien");else if(c.alignment=="Brak")parts.Add("Brâkmarien");else if(c.alignment=="Neutre")parts.Add("Neutre");return String.Join(" · ",parts);}
 internal static CompanionInstructionText Read(Store store,DofusCharacter c,string source,string context){source=source??"";string sourceHash=WorkspaceNext.Hash(Encoding.UTF8.GetBytes(source));string profile=Profile(c);string key=WorkspaceNext.Hash(Encoding.UTF8.GetBytes(Version+"/"+(c==null?"":c.id)+"/"+profile+"/"+(context??"")+"/"+sourceHash));string folder=Path.Combine(store.Root,"InstructionViews"),file=Path.Combine(folder,key+".json");try{if(File.Exists(file)&&new FileInfo(file).Length<=1024*1024){var cached=Json.Deserialize<CompanionInstructionText>(File.ReadAllText(file));if(cached!=null&&cached.version==Version&&cached.profile==profile&&cached.sourceHash==sourceHash&&cached.text!=null&&cached.text.Length<=60000)return cached;}}catch(IOException){}catch(UnauthorizedAccessException){}catch(ArgumentException){}catch(InvalidOperationException){}
 var result=new CompanionInstructionText{profile=profile,text=Rewrite(source),sourceHash=sourceHash,version=Version};try{Directory.CreateDirectory(folder);if(Directory.EnumerateFiles(folder,"*.json").Take(5001).Count()<5000){string temp=file+".tmp";File.WriteAllText(temp,Json.Serialize(result),new UTF8Encoding(false));if(File.Exists(file))File.Delete(file);File.Move(temp,file);}}catch(IOException){}catch(UnauthorizedAccessException){}return result;}
 internal static void Test(string folder){string original="Rendez-vous en [-3,2].\nParlez à Test-PNJ avec 3 ressources.\nNe tuez pas le gardien.\nSi vous êtes Iop, ne prenez pas ce chemin.\nChoisissez « Vous devez attendre 5 minutes ».\n• Récupérez 12 objets en [0,-1].\nN’oubliez pas le prérequis.";string text=Rewrite(original);if(!text.Contains("Va en [-3,2]")||!text.Contains("Parle à Test-PNJ avec 3 ressources")||!text.Contains("Ne tue pas le gardien")||!text.Contains("• Récupère 12 objets"))throw new Exception("Style compagnon non appliqué");if(!text.Contains("Si vous êtes Iop, ne prenez pas ce chemin.")||!text.Contains("Choisissez « Vous devez attendre 5 minutes ».")||!text.Contains("N’oublie pas le prérequis"))throw new Exception("Condition, dialogue ou négation altéré");if(String.Join("/",Regex.Matches(original,@"-?\d+").Cast<Match>().Select(m=>m.Value))!=String.Join("/",Regex.Matches(text,@"-?\d+").Cast<Match>().Select(m=>m.Value)))throw new Exception("Quantité ou position altérée");var store=new Store(Path.Combine(folder,"instruction-style"));var c=new DofusCharacter{id="one",name="Test",classCode="Sacri",alignment="Bonta"};var rendered=Read(store,c,original,"step");if(!rendered.profile.Contains("Sacrieur")||!rendered.profile.Contains("Bontarien")||Read(store,c,original,"step").text!=text)throw new Exception("Contexte personnage ou cache");Read(store,new DofusCharacter{id="two",name="Autre"},original,"step");Read(store,c,original+"\nAttention : 8 objets.","step");if(Directory.GetFiles(Path.Combine(store.Root,"InstructionViews"),"*.json").Length!=3)throw new Exception("Cache partagé ou source modifiée ignorée");PersonalWorkflows.Change(store,()=>store.Value.instructions.companion=false);if(new Store(store.Root).Value.instructions.companion)throw new Exception("Préférence texte source perdue");if(original.Contains("Va en"))throw new Exception("Source modifiée");}
}
